12		"github.com/openai/openai-go"
13	
14		candle_binding "github.com/vllm-project/semantic-router/candle-binding"
15		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/embedding"
16		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
17	)
18	
19	// ToolEntry represents a tool stored in the tools database
20	type ToolEntry struct {
21		Tool        openai.ChatCompletionToolParam `json:"tool"`
22		Description string                         `json:"description"` // Used for similarity matching
23		Embedding   []float32                      `json:"-"`           // Generated from description
24		Tags        []string                       `json:"tags,omitempty"`
25		Category    string                         `json:"category,omitempty"`
26	}
27	
28	// ToolSimilarity represents a tool candidate with its similarity score.
29	type ToolSimilarity struct {
30		Entry      ToolEntry
31		Similarity float32
32	}
33	
34	// ToolsDatabase manages a collection of tools with semantic search capabilities
35	type ToolsDatabase struct {
36		entries             []ToolEntry
37		mu                  sync.RWMutex
38		similarityThreshold float32
39		enabled             bool
40		modelType           string // Model type to use for embeddings (e.g., "mmbert", "qwen3", "gemma")
41		targetDim           int    // Target dimension for embeddings
42		provider            embedding.Provider
43	}
44	
45	// ToolsDatabaseOptions holds options for creating a new tools database
46	type ToolsDatabaseOptions struct {
47		SimilarityThreshold float32
48		Enabled             bool
49		ModelType           string // Model type to use for embeddings
50		TargetDimension     int    // Target dimension for embeddings
51		Provider            embedding.Provider
52	}
53	
54	// NewToolsDatabase creates a new tools database with the given options
55	func NewToolsDatabase(options ToolsDatabaseOptions) *ToolsDatabase {
56		return &ToolsDatabase{
57			entries:             []ToolEntry{},
58			similarityThreshold: options.SimilarityThreshold,
59			enabled:             options.Enabled,
60			modelType:           options.ModelType,
61			targetDim:           options.TargetDimension,
62			provider:            options.Provider,
63		}
64	}
65	
66	// IsEnabled returns whether the tools database is enabled
67	func (db *ToolsDatabase) IsEnabled() bool {
68		return db.enabled
69	}
70	
71	// LoadToolsFromFile loads tools from a JSON file
72	func (db *ToolsDatabase) LoadToolsFromFile(filePath string) error {
73		if !db.enabled {
74			return nil
75		}
76	
77		// Read the JSON file
78		data, err := os.ReadFile(filePath)
79		if err != nil {
80			return fmt.Errorf("failed to read tools file: %w", err)
81		}
82	
83		// Parse the JSON data into ToolEntry slice
84		var toolEntries []ToolEntry
85		if err := json.Unmarshal(data, &toolEntries); err != nil {
86			return fmt.Errorf("failed to parse tools JSON: %w", err)
87		}
88	
89		// Use worker pool for concurrent embedding generation
90		numWorkers := runtime.NumCPU() * 2
91		if numWorkers > len(toolEntries) {
92			numWorkers = len(toolEntries)
93		}
94		logging.ComponentEvent("tools", "tool_database_load_started", map[string]interface{}{
95			"file_path":        filePath,
96			"model_type":       db.modelType,
97			"target_dimension": db.targetDim,
98			"tool_count":       len(toolEntries),
99			"worker_count":     numWorkers,
100		})
101	
102		type result struct {
103			entry ToolEntry
104			err   error
105		}
106	
107		resultChan := make(chan result, len(toolEntries))
108		entryChan := make(chan ToolEntry, len(toolEntries))
109	
110		// Send all entries to channel
111		for _, entry := range toolEntries {
112			entryChan <- entry
113		}
114		close(entryChan)
115	
116		// Start workers
117		var wg sync.WaitGroup
118		for i := 0; i < numWorkers; i++ {
119			wg.Add(1)
120			go func(workerID int) {
121				defer wg.Done()
122				for entry := range entryChan {
123					embedding, err := db.embedText(entry.Description)
124					if err != nil {
125						resultChan <- result{entry: entry, err: err}
126					} else {
127						entry.Embedding = embedding
128						resultChan <- result{entry: entry, err: nil}
129					}
130				}
131			}(i)
132		}
133	
134		// Close result channel when all workers are done
135		go func() {
136			wg.Wait()
137			close(resultChan)
138		}()
139	
140		// Collect results
141		successCount := 0
142		failedCount := 0
143	
144		db.mu.Lock()
145		defer db.mu.Unlock()
146	
147		for res := range resultChan {
148			if res.err != nil {
149				logging.ComponentWarnEvent("tools", "tool_embedding_failed", map[string]interface{}{
150					"tool_name": res.entry.Tool.Function.Name,
151					"error":     res.err.Error(),
152				})
153				failedCount++
154			} else {
155				// Add to the database
156				db.entries = append(db.entries, res.entry)
157				logging.ComponentDebugEvent("tools", "tool_loaded", map[string]interface{}{
158					"tool_name":       res.entry.Tool.Function.Name,
159					"category":        res.entry.Category,
160					"has_tags":        len(res.entry.Tags) > 0,
161					"description_len": len(res.entry.Description),
162				})
163				successCount++
164			}
165		}
166	
167		logging.ComponentEvent("tools", "tool_database_loaded", map[string]interface{}{
168			"file_path":        filePath,
169			"model_type":       db.modelType,
170			"target_dimension": db.targetDim,
171			"tool_count":       len(toolEntries),
172			"loaded_count":     successCount,
173			"failed_count":     failedCount,
174			"worker_count":     numWorkers,
175		})
176		return nil
177	}
178	
179	// AddTool adds a tool to the database with automatic embedding generation
180	func (db *ToolsDatabase) AddTool(tool openai.ChatCompletionToolParam, description string, category string, tags []string) error {
181		if !db.enabled {
182			return nil
183		}
184	
185		embedding, err := db.embedText(description)
186		if err != nil {
187			return fmt.Errorf("failed to generate embedding for tool %s: %w", tool.Function.Name, err)
188		}
189	
190		entry := ToolEntry{Tool: tool, Description: description, Embedding: embedding, Category: category, Tags: tags}
191	
192		db.mu.Lock()
193		defer db.mu.Unlock()
194	
195		db.entries = append(db.entries, entry)
196		logging.ComponentEvent("tools", "tool_added", map[string]interface{}{
197			"tool_name":       tool.Function.Name,
198			"category":        category,
199			"has_tags":        len(tags) > 0,
200			"description_len": len(description),
201			"model_type":      db.modelType,
202		})
203	
204		return nil
205	}
206	
207	func (db *ToolsDatabase) similarityFloor(minOverride *float32) float32 {
208		if minOverride != nil {
209			return *minOverride
210		}
211		return db.similarityThreshold
212	}
213	
214	// FindSimilarTools finds the most similar tools based on the query
215	func (db *ToolsDatabase) FindSimilarTools(query string, topK int) ([]openai.ChatCompletionToolParam, error) {
216		results, err := db.FindSimilarToolsWithScores(query, topK)
217		if err != nil {
218			return nil, err
219		}
220	
221		selectedTools := make([]openai.ChatCompletionToolParam, len(results))
222		for i, result := range results {
223			selectedTools[i] = result.Entry.Tool
224		}
225	
226		return selectedTools, nil
227	}
228	
229	// FindSimilarToolsWithScores finds the most similar tools based on the query and returns scores.
230	func (db *ToolsDatabase) FindSimilarToolsWithScores(query string, topK int) ([]ToolSimilarity, error) {
231		return db.FindSimilarToolsWithScoresMinSimilarity(query, topK, nil)
232	}
233	
234	// FindSimilarToolsWithScoresMinSimilarity is like FindSimilarToolsWithScores but allows overriding
235	// the minimum similarity cutoff for this query (embedding dot-product scores).
236	func (db *ToolsDatabase) FindSimilarToolsWithScoresMinSimilarity(query string, topK int, minSimilarity *float32) ([]ToolSimilarity, error) {
237		if !db.enabled {
238			return []ToolSimilarity{}, nil
239		}
240	
241		queryEmbedding, err := db.embedText(query)
242		if err != nil {
243			return nil, fmt.Errorf("failed to generate embedding for query: %w", err)
244		}
245	
246		db.mu.RLock()
247		defer db.mu.RUnlock()
248	
249		// Calculate similarities
250		results := make([]ToolSimilarity, 0, len(db.entries))
251		for _, entry := range db.entries {
252			// Calculate similarity
253			var dotProduct float32
254			for i := 0; i < len(queryEmbedding) && i < len(entry.Embedding); i++ {
255				dotProduct += queryEmbedding[i] * entry.Embedding[i]
256			}
257	
258			floor := db.similarityFloor(minSimilarity)
259			logging.Debugf("Tool '%s' similarity score: %.4f (threshold: %.4f)",
260				entry.Tool.Function.Name, dotProduct, floor)
261	
262			if dotProduct >= floor {
263				results = append(results, ToolSimilarity{
264					Entry:      entry,
265					Similarity: dotProduct,
266				})
267			}
268		}
269	
270		// No results found
271		if len(results) == 0 {
272			return []ToolSimilarity{}, nil
273		}
274	
275		// Sort by similarity (highest first)
276		sort.Slice(results, func(i, j int) bool {
277			return results[i].Similarity > results[j].Similarity
278		})
279	
280		limit := topK
281		if limit <= 0 || limit > len(results) {
282			limit = len(results)
283		}
284	
285		selected := results[:limit]
286		for _, result := range selected {
287			logging.Infof("Selected tool: %s (similarity=%.4f)",
288				result.Entry.Tool.Function.Name, result.Similarity)
289		}
290	
291		logging.Infof("Found %d similar tools for query: %s", len(selected), logging.ContentDescriptor(query))
292		return selected, nil
293	}
294	
295	func (db *ToolsDatabase) embedText(text string) ([]float32, error) {
296		if db.provider != nil {
297			return db.provider.Embed(context.Background(), text)
298		}
299		output, err := candle_binding.GetEmbeddingWithModelType(text, db.modelType, db.targetDim)
300		if err != nil {
301			return nil, err
302		}
303		return output.Embedding, nil
304	}
305	
306	// GetAllTools returns all tools in the database
307	func (db *ToolsDatabase) GetAllTools() []openai.ChatCompletionToolParam {
308		if !db.enabled {
309			return []openai.ChatCompletionToolParam{}
310		}
311	
312		db.mu.RLock()
313		defer db.mu.RUnlock()
314	
315		tools := make([]openai.ChatCompletionToolParam, len(db.entries))
316		for i, entry := range db.entries {
317			tools[i] = entry.Tool
318		}
319	
320		return tools
321	}
322	
323	// GetToolCount returns the number of tools in the database
324	func (db *ToolsDatabase) GetToolCount() int {
325		if !db.enabled {
326			return 0
327		}
328	
329		db.mu.RLock()
330		defer db.mu.RUnlock()
331	
332		return len(db.entries)
333	}
